(5044696, 736606, 54645, '<td valign="top">excellent symmetry. The sky is beautiful.</td>', 'excellent symmetry. The sky is beautiful.', '2008-11-05 00:10:11.000000', NULL, 1),
(5044697, 736276, 98141, '<td valign="top">To me, having a clear object on a dark background would be more powerful.</td>', 'To me, having a clear object on a dark background would be more powerful.', '2008-11-05 00:10:24.000000', NULL, 1),
(5044703, 736715, 98141, '<td valign="top">Is she shaving her legs in the sink? Is he up the next morning about to shave? A little unclear. Great colors. Like the idea!</td>', 'Is she shaving her legs in the sink? Is he up the next morning about to shave? A little unclear. Great colors. Like the idea!', '2008-11-05 00:11:37.000000', NULL, 1),
