(5044719, 736171, 98141, '<td valign="top">I think I would like this more if the top of the plant were in the frame.</td>', 'I think I would like this more if the top of the plant were in the frame.', '2008-11-05 00:13:52.000000', NULL, 1),
(5044725, 736179, 98141, '<td valign="top">Nice focus, great colors. Dirty mirror is a little distracting.</td>', 'Nice focus, great colors. Dirty mirror is a little distracting.', '2008-11-05 00:15:03.000000', NULL, 1),
(5044972, 735808, 98141, '<td valign="top">Very cool, like a painting. Great colors.</td>', 'Very cool, like a painting. Great colors.', '2008-11-05 00:53:00.000000', NULL, 1),
(5044973, 735719, 98141, '<td valign="top">I like this idea a lot, but the shot seems kind of bland. Also, having the ground in one corner is distracting from the overall composition.</td>', 'I like this idea a lot, but the shot seems kind of bland. Also, having the ground in one corner is distracting from the overall composition.', '2008-11-05 00:53:01.000000', NULL, 1),
(5044974, 736361, 98141, '<td valign="top">I love the use of multiple mirrors here. The cord in the back is distracting. I think more vivid colors would look good.</td>', 'I love the use of multiple mirrors here. The cord in the back is distracting. I think more vivid colors would look good.', '2008-11-05 00:53:03.000000', NULL, 1),
