(5053007, 735808, 90495, '<td valign="top">4</td>', '4', '2008-11-08 21:07:32.000000', NULL, 1),
(5053294, 736394, 99858, '<td valign="top">I like the way the shot is set up and it really captures the essence of what the challenge (mirrored sunglasses) Though I would have like the shot better if there were no houses reflected in the glasses, but that is just my opinion.</td>', 'I like the way the shot is set up and it really captures the essence of what the challenge (mirrored sunglasses) Though I would have like the shot better if there were no houses reflected in the glasses, but that is just my opinion.', '2008-11-09 00:01:00.000000', NULL, 1),
