(5058541, 736099, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>well done, as always :-)</td>', 'PostLuminous Award Nominee!well done, as always :-)', '2008-11-12 01:03:43.000000', NULL, 0),
(5058543, 736415, 100140, '<td valign="top">I had intentionally created an empty area by not lighting the wooden table there, but I do understand, if I was to pull this off correctly next time, perhaps yeah I needed better lighting, and better focus on the girl. Thank you very much everyone for your help, my love for photography only needs experience! :P</td>', 'I had intentionally created an empty area by not lighting the wooden table there, but I do understand, if I was to pull this off correctly next time, perhaps yeah I needed better lighting, and better focus on the girl. Thank you very much everyone for your help, my love for photography only needs experience! :P', '2008-11-12 01:04:01.000000', NULL, 0),
(5058544, 735085, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>The luminous glow and and composition are perfect</td>', 'PostLuminous Award Nominee!The luminous glow and and composition are perfect', '2008-11-12 01:04:26.000000', NULL, 0),
